.custom_inventory_root
{
	horizontal-align: left;
	vertical-align: bottom;
	margin-bottom: 144px;
	opacity: 0.9;
	z-index: -1;
}

.custom_inventory_root.Hidden
{
	visibility: collapse;
}

.custom_inventory_container
{
	flow-children: right;
	background-color: #505050cc;
	box-shadow: 0px 2px 8px #0000004c;
	animation-name: custom_inventory_animation;
	animation-duration: 0.2s;
	animation-delay: 6s;
	animation-fill-mode: forwards;
	opacity: 0;
	padding: 2px;
	background-image: url("s2r://panorama/images/hud/reborn/inventory_bg_psd.vtex");
	background-size: 100%;
	border-bottom: 1px solid #000e;
	background-repeat: no-repeat;
	padding-left: 2px;
	padding-right: 0px;
}

.custom_inv_slot
{
	width: 62px;
	height: 42px;
	margin: 2px 2px -1px 2px;
	transition-property: opacity, saturation;
	transition-duration: 0.12s;
	transition-timing-function: ease-in-out;
}

.custom_inv_slot .item_box
{
	background-image: url("s2r://panorama/images/custom_game/icon/item_bg_png.vtex");
	background-size: 100% 100%;
	background-repeat: no-repeat;
	background-position: center;
}

.custom_inv_slot.custom_inv_slot_empty_count
{
	opacity: 0.45;
	saturation: 0.25;
}

.custom_inv_count_container
{
	horizontal-align: right;
	vertical-align: bottom;
	min-width: 18px;
	height: 16px;
	margin-right: 1px;
	margin-bottom: 0px;
	padding-left: 3px;
	padding-right: 3px;
	background-color: #000000c8;
	border-radius: 2px;
	z-index: 17;
}

.custom_inv_count_label
{
	color: #f0f0f0;
	font-size: 15px;
	font-weight: bold;
	text-align: right;
	horizontal-align: right;
	vertical-align: center;
	text-shadow: 0px 0px 4px 3 #000000;
}

.custom_inv_keybind_container
{
	margin-left: -1px;
	background-color: #212726;
	box-shadow: fill #000000aa 1px 1px 6px 0px;
	border-radius: 3px;
	border: 1px solid black;
	z-index: 16;
	margin-top: -2px;
	min-width: 15px;
	min-height: 14px;
	max-width: 70px;
	max-height: 15px;
	transition-property: border-brush, box-shadow;
	transition-duration: 0.1s;
	transition-timing-function: ease-in;
}

.custom_inv_keybind_container:hover
{
	background-color: #313736;
	brightness: 1.5;
	border-color: white;
